//! The repo contract: the files a repo must carry, the commands Hulahoop runs,
//! and the environment a run is allowed to see.

use crate::{RunFlag, CONTRACT_VERSION};
use std::path::{Path, PathBuf};

/// Files the repo must ship. `.envrc` is generated by the runner when missing,
/// which is why it is not in this list.
pub const REQUIRED_FILES: [&str; 2] = ["flake.nix", "justfile"];

/// Files whose modification means the run changed the toolchain or the test
/// command itself, so a human has to acknowledge it before approving.
pub const GATED_FILES: [&str; 4] = ["flake.nix", "flake.lock", "justfile", ".envrc"];

pub const ENVRC_CONTENT: &str = "use flake\n";

/// Whole-suite recipe. There is deliberately no per-test entry point: a suite
/// that is run selectively stops being proof of anything.
pub fn test_command() -> Vec<String> {
    vec![
        "direnv".into(),
        "exec".into(),
        ".".into(),
        "just".into(),
        "test".into(),
    ]
}

pub fn setup_command() -> Vec<String> {
    vec![
        "direnv".into(),
        "exec".into(),
        ".".into(),
        "just".into(),
        "setup".into(),
    ]
}

pub fn contract_metadata_command() -> Vec<String> {
    vec![
        "nix".into(),
        "flake".into(),
        "metadata".into(),
        "--no-write-lock-file".into(),
    ]
}

/// Preflight for one adapter inside a repo's dev shell.
pub fn probe_command(adapter: crate::Adapter, model: &str) -> Vec<String> {
    use crate::Adapter;
    match adapter {
        Adapter::Pi => vec![
            "direnv".into(),
            "exec".into(),
            ".".into(),
            "pi".into(),
            "--version".into(),
        ],
        Adapter::ClaudeCode => vec![
            "direnv".into(),
            "exec".into(),
            ".".into(),
            "claude".into(),
            "--version".into(),
        ],
        // The scripted adapter has no CLI, so there is nothing to resolve through
        // a dev shell: the probe is the shell itself.
        Adapter::Fake => vec!["sh".into(), "-c".into(), format!("echo fake {model}")],
    }
}

/// Env vars a run is allowed to inherit from the runner, before the allowlist
/// the runner adds. Everything else is dropped by `env_clear`.
pub const INHERITED_ENV: [&str; 6] = ["PATH", "TMPDIR", "TERM", "LANG", "LC_ALL", "USER"];

/// Variables Hulahoop sets itself. Passed by name, never inherited wholesale.
pub const HULAHOOP_ENV: [&str; 8] = [
    "HULAHOOP_INPUT",
    "HULAHOOP_RUN_ID",
    "HULAHOOP_AGENT",
    "HULAHOOP_CHECKOUT",
    "HULAHOOP_ARTIFACT_DIR",
    "HULAHOOP_TESTS_BOOKMARK",
    "HULAHOOP_BASE_BOOKMARK",
    "HULAHOOP_PROMPT",
];

/// Adapter credentials that must survive the clean environment.
pub const CREDENTIAL_ENV: [&str; 8] = [
    "ANTHROPIC_API_KEY",
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_BASE_URL",
    "OPENAI_API_KEY",
    "OPENAI_BASE_URL",
    "PI_API_KEY",
    "PI_MODEL",
    "CLAUDE_CONFIG_DIR",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PathVerdict {
    /// Implementation code, free to change.
    Allowed,
    /// A contract file: allowed, but the approval has to acknowledge it.
    Gated(RunFlag),
    /// A frozen test: the run is rejected.
    Frozen,
}

/// Classify one changed path against the frozen suite and the contract.
pub fn classify_path(path: &str, frozen_paths: &[String]) -> PathVerdict {
    let normalized = path.trim_start_matches("./");
    if frozen_paths
        .iter()
        .any(|p| p.trim_start_matches("./") == normalized)
    {
        return PathVerdict::Frozen;
    }
    if GATED_FILES.contains(&normalized) {
        return PathVerdict::Gated(RunFlag::TouchedContract);
    }
    PathVerdict::Allowed
}

/// Paths that must never enter a run diff.
pub fn is_excluded(path: &str) -> bool {
    let p = path.trim_start_matches("./");
    p == ".envrc" || p == ".hulahoop" || p.starts_with(".hulahoop/")
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PreflightError {
    MissingFiles(Vec<String>),
    FlakeFails(String),
    JustFails(String),
    VersionMismatch { found: String },
}

impl std::fmt::Display for PreflightError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PreflightError::MissingFiles(files) => write!(
                f,
                "this repo is not a Hulahoop contract repo: missing {}. Hulahoop needs a flake.nix and a justfile with `setup` and `test` recipes (contract {}).",
                files.join(", "),
                CONTRACT_VERSION
            ),
            PreflightError::FlakeFails(msg) => write!(
                f,
                "flake.nix does not evaluate in this repo: {msg}. Run `nix flake metadata` there and fix the error before adding the repo."
            ),
            PreflightError::JustFails(msg) => write!(
                f,
                "the justfile does not expose `setup` and `test`: {msg}. Both recipes are required (contract {}).",
                CONTRACT_VERSION
            ),
            PreflightError::VersionMismatch { found } => write!(
                f,
                "this repo was last used with Hulahoop contract {found}, this build speaks {CONTRACT_VERSION}. Run the migration steps in README §7, or create a fresh checkout of the repo."
            ),
        }
    }
}

/// Cheap structural preflight, before any command runs.
pub fn check_files(root: &Path) -> Result<(), PreflightError> {
    let missing: Vec<String> = REQUIRED_FILES
        .iter()
        .filter(|name| !root.join(name).exists())
        .map(|name| (*name).to_string())
        .collect();
    if missing.is_empty() {
        Ok(())
    } else {
        Err(PreflightError::MissingFiles(missing))
    }
}

/// `direnv exec` needs an `.envrc`; the runner writes one when the repo lacks it
/// and allows it for that path. A committed `.envrc` is left alone (and gated).
pub fn needs_generated_envrc(root: &Path) -> bool {
    !root.join(".envrc").exists()
}

pub fn checkout_dir(data_dir: &Path, project: &str, issue: &uuid::Uuid, owner: &str) -> PathBuf {
    data_dir
        .join("checkouts")
        .join(project)
        .join(issue.to_string())
        .join(owner)
}

/// Where a run works when the checkout has to be produced rather than borrowed.
///
/// The tree is `workspace/<project>/<issue>/<run>/checkout`, because the numbers
/// multiply: a project holds issues, an issue holds attempts, an attempt holds one
/// run per role, and every level has to be findable a year later. Deletion is by
/// the run directory, so nothing above it can be caught by accident.
pub fn workspace_checkout_dir(
    data_dir: &Path,
    project: &str,
    issue: &uuid::Uuid,
    run: &uuid::Uuid,
) -> PathBuf {
    data_dir
        .join("workspace")
        .join(project)
        .join(issue.to_string())
        .join(run.to_string())
        .join("checkout")
}

/// The repository a local runner clones from when the repo has no remote of its
/// own. One constant while there is one project; it becomes a column the day a
/// second project exists.
pub const DEFAULT_CLONE_URL: &str = "https://github.com/theskilllab/hulahoop.git";

pub fn run_artifact_dir(data_dir: &Path, run_id: &uuid::Uuid) -> PathBuf {
    data_dir.join("runs").join(run_id.to_string())
}

pub fn replay_artifact_dir(data_dir: &Path, replay_id: &uuid::Uuid) -> PathBuf {
    data_dir.join("replays").join(replay_id.to_string())
}

pub fn scratch_home(data_dir: &Path, adapter: crate::Adapter) -> PathBuf {
    data_dir.join("home").join(adapter.as_str())
}

pub fn connection_file(data_dir: &Path) -> PathBuf {
    data_dir.join("connection.json")
}

pub fn database_file(data_dir: &Path) -> PathBuf {
    data_dir.join("hulahoop.sqlite")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_workspace_checkout_is_findable_by_project_issue_and_run() {
        let project = uuid::Uuid::nil();
        let issue = uuid::Uuid::now_v7();
        let run = uuid::Uuid::now_v7();
        let path = workspace_checkout_dir(
            std::path::Path::new("/data"),
            &project.to_string(),
            &issue,
            &run,
        );
        assert!(path.ends_with("checkout"));
        let text = path.to_string_lossy();
        assert!(text.contains(&project.to_string()));
        assert!(text.contains(&issue.to_string()));
        assert!(text.contains(&run.to_string()));
        // The run directory is what a cleanup deletes, so nothing above it can be
        // caught by a parent-relative removal.
        assert_eq!(
            path.parent()
                .map(|dir| dir.file_name().unwrap().to_string_lossy().to_string()),
            Some(run.to_string())
        );
    }

    #[test]
    fn frozen_tests_win_over_the_contract() {
        let frozen = vec!["tests/test_calc.py".to_string()];
        assert_eq!(
            classify_path("tests/test_calc.py", &frozen),
            PathVerdict::Frozen
        );
        assert_eq!(
            classify_path("./justfile", &frozen),
            PathVerdict::Gated(RunFlag::TouchedContract)
        );
        assert_eq!(classify_path("calc.py", &frozen), PathVerdict::Allowed);
    }

    #[test]
    fn generated_envrc_never_reaches_a_diff() {
        assert!(is_excluded(".envrc"));
        assert!(is_excluded("./.hulahoop/junit.xml"));
        assert!(!is_excluded("justfile"));
    }

    #[test]
    fn missing_contract_files_are_named() {
        let err = check_files(Path::new("/nonexistent-repo")).unwrap_err();
        assert!(matches!(err, PreflightError::MissingFiles(_)));
        let message = err.to_string();
        assert!(message.contains("flake.nix"));
        assert!(message.contains("justfile"));
    }
}
